import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"Phase 4 · Proactive Service and Mobile Entry","description":"Work proactively within limited authority and use the phone for approval and takeover.","frontmatter":{"title":"Phase 4 · Proactive Service and Mobile Entry","description":"Work proactively within limited authority and use the phone for approval and takeover.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-4.md","filePath":"en/delivery/stage-4.md","lastUpdated":1794209603000}'),i={name:"en/delivery/stage-4.md"};function n(s,e,l,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="phase-4-·-proactive-service-and-mobile-entry" tabindex="-1">Phase 4 · Proactive Service and Mobile Entry <a class="header-anchor" href="#phase-4-·-proactive-service-and-mobile-entry" aria-label="Permalink to &quot;Phase 4 · Proactive Service and Mobile Entry&quot;">​</a></h1><p>See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 Delivery Status</a> for implemented scope, verified paths, and deliberate gaps.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented code loop:</strong> Six trigger types, proactive suggestions with provenance and risk, a proactive inbox with accept, ignore, snooze, and convert actions, attention budgets, quiet hours, and a pause entry. The web app ships an installable PWA shell, offline app shell, and mobile bottom navigation; Feishu long-connection messaging provides text approval from a phone.</li><li><strong>Still open:</strong> Real-device iOS/Android installation acceptance, phone pairing, system push, remote approval and takeover, and interruption acceptance with 5–10 real proactive tasks. See <a href="/hearth-os/en/delivery/status.html">Phase 2–6 delivery status</a>.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 4 lets Hearth work proactively within limited authority and turns the phone into an entry for viewing, approval, and takeover. The point is not automatic running; it is doing the right thing at the right time without creating noise.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-4/4-1.html">4.1 Set triggers and proactive suggestions</a></td><td>Find work worth doing and explain why it matters now.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-2.html">4.2 Build the proactive inbox</a></td><td>Gather suggestions where they are easy to judge and handle.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-3.html">4.3 View, approve, and take over on the phone</a></td><td>Keep only key actions and short-lived authority on the phone, revocable if lost.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-4/4-4.html">4.4 Control interruption and accept proactive service</a></td><td>Proactive mode must be quiet, useful, controllable, and easy to turn off.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>First create triggers and proactive suggestions without automatic execution.</li><li>Then gather suggestions in a proactive inbox where the user can accept, ignore, or turn them into tasks.</li><li>Then deliver the phone entry for viewing, approval, and takeover.</li><li>Finally accept with an attention budget and real tasks so proactive mode stays quiet, controllable, and revocable.</li></ol>',10)])])}const v=t(i,[["render",n]]);export{u as __pageData,v as default};
